func indexWithRows(lines ...string) string {
	out := "# Project Index\n\n## Source Documents\n"
	for _, line := range lines {
		if line == "" {
			out += "\n"
			continue
		}
		if len(line) >= 2 && line[:2] == "##" {
			out += line + "\n"
			continue
		}
		out += line + "\n"
		if line[0] == '|' && line[1] != '-' && line[2] != '-' {
			// separator rows are intentionally optional in fixtures.
		}
	}
	return out
}

