cat > /tmp/opencode/markerrepro/repro/repro_test.go <<'EOF'
package repro

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const lowercaseStatusRoadmap = `# Demo Roadmap

## Phase 1: Delivery

### Sprint 2: Second

> slug: 02-second
>status: active

#### Goal

Goal.

#### Build

- item

#### Acceptance

- [ ] ok
`

func TestLowercaseStatusAcceptedByParser(t *testing.T) {
	roadmap, issues := ParseRoadmap(lowercaseStatusRoadmap)
	if len(issues) != 0 {
		t.Fatalf("parser rejected grammar-valid lowercase metadata: %+v", issues)
	}
	if len(roadmap.Sprints) != 1 || roadmap.Sprints[0].Slug != "02-second" || roadmap.Sprints[0].Status != RoadmapActive {
		t.Fatalf("sprints = %+v", roadmap.Sprints)
	}
}

func TestMarkDeliveredWithLowercaseStatusCorrupts(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "roadmap.md")
	if err := os.WriteFile(path, []byte(lowercaseStatusRoadmap), 0o644); err != nil {
		t.Fatal(err)
	}
	changed, err := MarkRoadmapSprintDelivered(path, "02-second")
	if err != nil || !changed {
		t.Fatalf("first call changed=%t err=%v", changed, err)
	}
	data, _ := os.ReadFile(path)
	content := string(data)
	statusLines := 0
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.ToLower(strings.TrimSpace(line))
		if strings.HasPrefix(trimmed, ">") && strings.Contains(trimmed, "status:") {
			statusLines++
		}
	}
	if statusLines != 1 {
		t.Fatalf("expected exactly 1 status line after marking, got %d:\n%s", statusLines, content)
	}
	reparsed, issues := ParseRoadmap(content)
	if len(issues) != 0 {
		t.Fatalf("issues = %+v", issues)
	}
	if reparsed.Sprints[0].Status != RoadmapDelivered {
		t.Fatalf("delivery did not persist; status = %q\nfile:\n%s", reparsed.Sprints[0].Status, content)
	}
	// Second smoke pass on the still-planned roadmap:
	changedAgain, err := MarkRoadmapSprintDelivered(path, "02-second")
	if err != nil {
		t.Fatalf("second call err=%v", err)
	}
	if !changedAgain {
		t.Log("second call reported idempotent (unexpected under corruption)")
	}
}

func TestSpaceBeforeColonAlsoMissed(t *testing.T) {
	content := strings.Replace(lowercaseStatusRoadmap, ">status: active", "> Status : active", 1)
	dir := t.TempDir()
	path := filepath.Join(dir, "roadmap.md")
	os.WriteFile(path, []byte(content), 0o644)
	roadmap, issues := ParseRoadmap(content)
	if len(issues) != 0 || roadmap.Sprints[0].Status != RoadmapActive {
		t.Fatalf("grammar-valid variant rejected: issues=%+v sprints=%+v", issues, roadmap.Sprints)
	}
	_, err := MarkRoadmapSprintDelivered(path, "02-second")
	if err != nil {
		t.Fatal(err)
	}
	data, _ := os.ReadFile(path)
	reparsed, _ := ParseRoadmap(string(data))
	if reparsed.Sprints[0].Status != RoadmapDelivered {
		t.Fatalf("space-before-colon variant also fails to persist; status=%q\n%s", reparsed.Sprints[0].Status, data)
	}
}
EOF
cd /tmp/opencode/markerrepro && go test ./repro/ -run 'TestLowercase|TestMarkDelivered|TestSpaceBefore' -v 2>&1 | tail -30

